changeSet.sql:
if exists(select 1 from sys.indexes where name = 'CIX_GraphAssetNode_AssetId')
begin
	DROP INDEX [CIX_GraphAssetNode_AssetId] ON [graph].[AssetNode] WITH ( ONLINE = OFF );
end

changeSet.rollback:
if not exists(select 1 from sys.indexes where name = 'CIX_GraphAssetNode_AssetId')
begin
	CREATE UNIQUE CLUSTERED INDEX [CIX_GraphAssetNode_AssetId] ON [graph].[AssetNode] ( [ID] ASC );
end

changeSet.sql:
if not exists(select 1 from sys.key_constraints where name = 'PK_GraphAssetNode')
begin
	ALTER TABLE graph.AssetNode ADD CONSTRAINT PK_GraphAssetNode PRIMARY KEY CLUSTERED (ID);
end

changeSet.rollback:
if exists(select 1 from sys.key_constraints where name = 'PK_GraphAssetNode')
begin
	ALTER TABLE [graph].[AssetNode] DROP CONSTRAINT [PK_GraphAssetNode] WITH ( ONLINE = OFF );
end

changeSet.sql:
if not exists(select 1 from sys.indexes where name = 'IX_XML_GraphAssetNode_Segments_Primary')
begin
	CREATE PRIMARY XML INDEX IX_XML_GraphAssetNode_Segments_Primary on graph.AssetNode (Segments); 
end
if not exists(select 1 from sys.indexes where name = 'IX_XML_GraphAssetNode_Segments_Path')
begin
	CREATE XML INDEX IX_XML_GraphAssetNode_Segments_Path ON graph.AssetNode (Segments) USING XML INDEX IX_XML_GraphAssetNode_Segments_Primary FOR PATH;  
end
